import * as THREE from 'three/webgpu';
import { texture, uv, positionLocal, normalLocal, vec3, float, uniform, MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-pricing-row-parallax';

  const pos = config.position || [1.25, -0.2, 0];
  const rot = config.rotation || [0, 0, 0];
  const scl = config.scale || [1, 1, 1];
  group.position.set(pos[0], pos[1], pos[2]);
  group.rotation.set(rot[0], rot[1], rot[2]);
  group.scale.set(scl[0], scl[1], scl[2]);

  const imageUrl = '/prism-mock/home/nodes/parallax-stack.png';
  const depthMapUrl = '/prism-mock/home/nodes/parallax-stack.depth.png';

  const colorMap = ctx.textureLoader.load(imageUrl);
  const depthMap = ctx.textureLoader.load(depthMapUrl);
  colorMap.colorSpace = THREE.SRGBColorSpace;

  const geometry = new THREE.PlaneGeometry(3.2, 0.9, 64, 64);

  const displacementStrength = uniform(0.08);
  const hoverAmount = uniform(0.0);

  const depthSample = texture(depthMap, uv()).r;
  const displaced = positionLocal.add(
    normalLocal.mul(depthSample.sub(0.5)).mul(displacementStrength.add(hoverAmount))
  );

  const material = new MeshBasicNodeMaterial();
  material.colorNode = texture(colorMap, uv());
  material.positionNode = displaced;

  const mesh = new THREE.Mesh(geometry, material);
  mesh.name = 'pricing-row-plane';
  group.add(mesh);

  // Subtle divider line beneath the row
  const dividerGeo = new THREE.PlaneGeometry(3.2, 0.01);
  const dividerMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(config.colors?.paper || '#e8ecf2'), transparent: true, opacity: 0.25 });
  const divider = new THREE.Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -0.48, 0.001);
  group.add(divider);

  // Apply cinematic primitives per config
  const primitivesConfig = config.cinematicPrimitives || [
    { name: 'parallax-scroll', trigger: 'scroll', params: { intensity: 0.4 } },
    { name: 'depth-rotate', trigger: 'hover', params: { maxDeg: 8 } }
  ];

  const primitiveHandles = [];
  primitivesConfig.forEach((p) => {
    if (ctx.primitives && typeof ctx.primitives[p.name] === 'function') {
      const handle = ctx.primitives[p.name](group, p.params || {});
      if (handle) primitiveHandles.push(handle);
    }
  });

  // Hover: rise-in subtle preset (0.15 units) + displacement bump
  let hoverTimeline = null;
  const baseY = group.position.y;

  const onPointerOver = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, { y: baseY + 0.15, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTimeline.to(hoverAmount, { value: 0.05, duration: 0.3, ease: 'power2.out' }, 0);
  };

  const onPointerOut = () => {
    if (hoverTimeline) hoverTimeline.kill();
    hoverTimeline = gsap.timeline();
    hoverTimeline.to(group.position, { y: baseY, duration: 0.7, ease: 'power3.out' }, 0);
    hoverTimeline.to(hoverAmount, { value: 0.0, duration: 0.3, ease: 'power2.out' }, 0);
  };

  const onClick = () => {
    gsap.to(mesh.scale, {
      x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out',
      yoyo: true, repeat: 1,
      onComplete: () => {
        if (ctx.emit) {
          ctx.emit('hub-pricing.select', { nodeId: group.name });
        }
      }
    });
  };

  group.userData.handlers = {
    onPointerOver,
    onPointerOut,
    onClick
  };

  // Data binding placeholder: trpc.visits.book.slot -> confirmPanel
  group.userData.bindings = {
    confirmPanel: null
  };
  group.userData.applyBinding = (data) => {
    group.userData.bindings.confirmPanel = data;
  };

  group.userData.cleanup = () => {
    if (hoverTimeline) hoverTimeline.kill();
    primitiveHandles.forEach((h) => {
      if (h && typeof h.dispose === 'function') h.dispose();
    });
    geometry.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    material.dispose();
    if (colorMap && colorMap.dispose) colorMap.dispose();
    if (depthMap && depthMap.dispose) depthMap.dispose();
  };

  return group;
}
